  if (callingCode === '44') return /^(?:7700900\d{3}|2079460\d{3}|1632960\d{3}|1134960\d{3}|1214960\d{3}|1314960\d{3}|1414960\d{3}|1514960\d{3}|1614960\d{3}|1914960\d{3}|1174960\d{3})$/.test(national);
