    status: fictional ? 'fictional' : 'valid',
    reason: fictional ? 'reserved_fictional_range' : null,
    e164,
    countryIso: info.iso,
    callingCode: info.callingCode,
    nationalNumber: national,
    extension,
    issues,
  });
